text:
{
  "title": "استمارة التقديم على الوظائف ونموذج إقرار معالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "يُعتبر تقديم المتقدم لهذا الطلب وبدء استكمال نموذج التوظيف موافقة ضمنية ونهائية على جمع ومعالجة وتخزين كافة البيانات المقدمة واستخدامها للأغراض التشغيلية للشركة، ولا يحق للمتقدم طلب سحب هذه الموافقة أو تقييد صلاحيات المعالجة بعد إرسال النموذج تحت أي ظرف."
    },
    {
      "slot": "p2",
      "text": "نقوم بإتلاف المستندات والبيانات الخاصة بطلبات التوظيف نهائياً ودون تأخير فور انقضاء الغرض المحدد من جمعها، باستثناء السجلات التي توجب المتطلبات التنظيمية أو المحاسبية أو القضايا العمالية المحتملة الاحتفاظ بها لمدة أطول."
    },
    {
      "slot": "p3",
      "text": "يحق للمتقدم في أي وقت طلب الاطلاع على بياناته الشخصية المسجلة لدينا، أو طلب تصحيحها أو استكمالها، فضلاً عن تقديم طلب بإتلافها في حال انتفاء الحاجة إليها لأغراض التوظيف."
    },
    {
      "slot": "p4",
      "text": "تلتزم الشركة بجمع القدر الكافي والمناسب من البيانات الشخصية للمتقدمين بما يخدم مصلحة العمل والتقييم المهني دون إفراط."
    }
  ],
  "neutral": [
    "تخضع كافة التعاقدات والنزاعات الناشئة عن هذا الطلب لأنظمة المملكة العربية السعودية وحدها.",
    "تعني كلمة \"الشركة\" في هذا المستند شركة التقنية المتقدمة للخدمات المهنية، ويعني مصطلح \"المتقدم\" الشخص الطبيعي المقدم لطلب الوظيفة.",
    "تتحمل الشركة المسؤولية المدنية الكاملة عن أي أضرار مباشرة تثبت ناتجة عن إهمال جسيم في تنفيذ التزاماتها التعاقدية.",
    "يحق لأي من الطرفين إنهاء هذه الإرادة التعاقدية المبدئية بموجب إشعار خطي يوجه للطرف الآخر قبل موعد الإلغاء بثلاثين يوماً.",
    "تظل كافة حقوق الملكية الفكرية والعلامات التجارية وبراءات الاختراع الخاصة بالشركة مملوكة لها وحدها ولا تنتقل بأي شكل من الأشكال.",
    "تتم كافة المراسلات الرسمية والإشعارات المتعلقة بهذا النموذج عبر البريد الإلكتروني المسجل للمتقدم أو بالعنوان الوطني المعتمد."
  ]
}
